import{G as e,K as t,at as n,n as r}from"./chunks/framework.CKwzX5kV.js";var i=JSON.parse(`{"title":"什么是 MCP？","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"zh/guide/what-is-mcp.md","filePath":"zh/guide/what-is-mcp.md"}`),a={name:`zh/guide/what-is-mcp.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="什么是-mcp" tabindex="-1">什么是 MCP？ <a class="header-anchor" href="#什么是-mcp" aria-label="Permalink to “什么是 MCP？”">​</a></h1><p>模型上下文协议（Model Context Protocol，MCP）是一个开放协议，它标准化了应用程序如何向大型语言模型（LLMs）提供上下文。可以将 MCP 想象成 AI 应用程序的 USB-C 接口。就像 USB-C 为连接设备与各种外设和配件提供了标准化方式一样，MCP 为连接 AI 模型与不同数据源和工具提供了标准化方式。MCP 使您能够在 LLMs 之上构建代理和复杂工作流，并将您的模型与世界连接起来。</p><p>MCP 提供：</p><ul><li><strong>不断增长的预构建集成列表</strong>，您的 LLM 可以直接插入使用</li><li><strong>构建 AI 应用程序自定义集成的标准化方式</strong></li><li><strong>一个人人都可以自由实现和使用的开放协议</strong></li><li><strong>在不同应用程序之间切换的灵活性</strong>，并且可以随身携带您的上下文</li></ul><p>如果想了解更多，请访问 MCP 官网：<a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/</a></p>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};